import sys
import json
import os

def format_date(d):
    if not d:
        return "ABSENT"
    if len(d) == 8 and d.isdigit():
        return f"{d[:4]}-{d[4:6]}-{d[6:]}"
    return d

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    fda_file = os.path.join(packet_dir, 'fda_enforcement_reports.json')

    records = {}
    if os.path.exists(fda_file):
        with open(fda_file, 'r') as f:
            data = json.load(f)
            for result in data.get('results', []):
                entity = result.get('recall_number')
                if not entity:
                    continue

                init_date = format_date(result.get('recall_initiation_date', ''))
                class_date = format_date(result.get('center_classification_date', ''))
                term_date = format_date(result.get('termination_date', ''))

                if entity not in records:
                    records[entity] = {
                        'initiation date': set(),
                        'classification date': set(),
                        'termination date': set()
                    }

                records[entity]['initiation date'].add(init_date)
                records[entity]['classification date'].add(class_date)
                records[entity]['termination date'].add(term_date)

    output = {}
    for pair in manifest.get('pairs', []):
        rule_id, entity = pair.split('::')
        facts = manifest.get('facts', {}).get(rule_id, [])

        output[pair] = {}
        for fact in facts:
            if entity not in records:
                output[pair][fact] = "ABSENT"
            else:
                vals = records[entity].get(fact, set())
                if len(vals) == 0:
                    output[pair][fact] = "ABSENT"
                elif len(vals) == 1:
                    val = list(vals)[0]
                    if val == "ABSENT":
                        output[pair][fact] = "ABSENT"
                    else:
                        output[pair][fact] = [val, "fda_enforcement_reports"]
                else:
                    output[pair][fact] = "CONFLICT"

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
