import sys
import json
import os

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    fda_file = os.path.join(packet_dir, 'fda_enforcement_reports.json')

    entity_field_values = {}

    if os.path.exists(fda_file):
        with open(fda_file, 'r') as f:
            fda_data = json.load(f)

        for result in fda_data.get('results', []):
            entity = result.get('recall_number')
            if not entity:
                continue

            if entity not in entity_field_values:
                entity_field_values[entity] = {}

            for field in ["recall_initiation_date", "center_classification_date", "termination_date"]:
                val = result.get(field, "")
                if not val:
                    val_fmt = "ABSENT"
                elif len(val) == 8 and val.isdigit():
                    val_fmt = f"{val[:4]}-{val[4:6]}-{val[6:]}"
                else:
                    val_fmt = val

                if field not in entity_field_values[entity]:
                    entity_field_values[entity][field] = set()
                entity_field_values[entity][field].add(val_fmt)

    fact_to_field = {
        "initiation date": "recall_initiation_date",
        "classification date": "center_classification_date",
        "termination date": "termination_date"
    }

    output = {}
    for pair in manifest.get("pairs", []):
        rule_id, entity = pair.split("::")
        facts = manifest.get("facts", {}).get(rule_id, [])

        pair_result = {}
        for fact in facts:
            field = fact_to_field.get(fact)
            if not field:
                pair_result[fact] = "ABSENT"
                continue

            values = entity_field_values.get(entity, {}).get(field, set())

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) == 1:
                val = list(values)[0]
                if val == "ABSENT":
                    pair_result[fact] = "ABSENT"
                else:
                    pair_result[fact] = [val, "fda_enforcement_reports"]
            else:
                pair_result[fact] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
